import 'package:flutter/material.dart';
import '../../services/chat_service.dart';
class DeliveryChatScreen extends StatefulWidget{final int orderId;final String? customerName;const DeliveryChatScreen({super.key,required this.orderId,this.customerName});@override State<DeliveryChatScreen> createState()=>_DeliveryChatScreenState();}
class _DeliveryChatScreenState extends State<DeliveryChatScreen>{final s=DeliveryChatService();final c=TextEditingController();bool loading=true,sending=false;String? error;@override void initState(){super.initState();_connect();}Future<void> _connect()async{try{await s.connect(widget.orderId); await s.markRead(); if(mounted)setState(()=>loading=false);}catch(e){if(mounted)setState(()=>{loading=false,error=e.toString()});}}Future<void> _send()async{final t=c.text.trim();if(t.isEmpty||sending)return;setState(()=>sending=true);try{await s.send(t);c.clear();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>sending=false);}}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('Chat • ${widget.customerName??'Customer'}')),body:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Text(error!)):Column(children:[Expanded(child:StreamBuilder<List<Map<String,dynamic>>>(stream:s.messages(),builder:(c,snap){final ms=snap.data??[];return ListView.builder(reverse:true,itemCount:ms.length,itemBuilder:(c,i){final m=ms[ms.length-1-i];final mine=m['sender']=='delivery';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.symmetric(horizontal:12,vertical:4),padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),constraints:BoxConstraints(maxWidth:MediaQuery.of(context).size.width*.78),decoration:BoxDecoration(color:mine?Theme.of(context).colorScheme.primary:Colors.grey.shade200,borderRadius:BorderRadius.circular(16)),child:Text('${m['message']??''}',style:TextStyle(color:mine?Colors.white:Colors.black87)));});})),SafeArea(child:Row(children:[Expanded(child:TextField(controller:c,minLines:1,maxLines:4,decoration:const InputDecoration(hintText:'Message customer...',contentPadding:EdgeInsets.symmetric(horizontal:16)))),IconButton(onPressed:_send,icon:sending?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.send))]))]);}
